export function icon(name, { size, cls = '', label } = {}) {
  const body = paths[name] ?? paths.circle;
  const style = size ? ` style="width:${size}px;height:${size}px"` : '';
  const aria = label ? ` role="img" aria-label="${label}"` : ' aria-hidden="true"';
  return `<svg class="icon ${cls}" viewBox="0 -960 960 960" fill="currentColor"${style}${aria}><path d="${body}"/></svg>`;
}

export const hasIcon = (name) => name in paths;
